import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId } from "../api";

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const mData = await getMatchId(matchId);
      setMatch(mData);
      setLoading(false);
    };
    fetchData();
  }, [matchId]);

  if (loading)
    return (
      <div className="h-screen flex items-center justify-center bg-gray-950 text-red-600 font-black tracking-[0.3em] uppercase animate-pulse">
        Анализ матча...
      </div>
    );
  if (!match)
    return (
      <div className="text-center p-20 text-white font-black uppercase">
        Матч не найден
      </div>
    );

  const ResultCircle = ({ res }) => {
    const colors = { W: "bg-green-500", D: "bg-gray-500", L: "bg-red-500" };
    return (
      <span
        className={`${colors[res]} w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[9px] md:text-[10px] font-black text-white shadow-lg`}
      >
        {res}
      </span>
    );
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-8 text-white font-sans">
      {/* 1. ГЛАВНЫЙ ЭКРАН: КОМАНДЫ, ELO И ФОРМА */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-8 md:p-12 rounded-[40px] border border-gray-800 shadow-2xl relative overflow-hidden mb-10">
        {/* Хозяева */}
        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[10px] font-black text-yellow-500 bg-gray-800 px-4 py-1 rounded-full mb-4 tracking-widest">
            ELO: {Math.round(match.homeTeam.elo)}
          </div>
          <img
            src={match.homeTeam.logo_url}
            className="h-28 w-28 md:h-40 md:w-40 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center">
            {match.homeTeam.name_ru || match.homeTeam.name}
          </h1>
          <div className="flex gap-1.5 mt-4">
            {match.homeTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>

        {/* Время и статус (Центр) */}
        <div className="flex flex-col items-center my-8 md:my-0">
          <span className="text-5xl md:text-6xl font-black text-gray-800 italic mb-4">
            VS
          </span>
          {match.status === "FINISHED" ? (
            <div className="text-4xl font-black text-white bg-white/10 px-6 py-2 rounded-2xl">
              {match.score.home} : {match.score.away}
            </div>
          ) : (
            <div className="text-center">
              <div className="text-xs font-bold text-gray-500 tracking-widest uppercase mb-1">
                {new Date(match.utcDate).toLocaleDateString("ru-RU", {
                  day: "2-digit",
                  month: "2-digit",
                })}
              </div>
              <div className="text-2xl font-black text-white">
                {new Date(match.utcDate).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </div>
            </div>
          )}
        </div>

        {/* Гости */}
        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[10px] font-black text-yellow-500 bg-gray-800 px-4 py-1 rounded-full mb-4 tracking-widest">
            ELO: {Math.round(match.awayTeam.elo)}
          </div>
          <img
            src={match.awayTeam.logo_url}
            className="h-28 w-28 md:h-40 md:w-40 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center">
            {match.awayTeam.name_ru || match.awayTeam.name}
          </h1>
          <div className="flex gap-1.5 mt-4">
            {match.awayTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>
      </div>

      {/* 2. ПРОГНОЗ НЕЙРОСЕТИ */}
      {match.prediction && (
        <div className="bg-gray-900 rounded-[40px] p-8 md:p-12 mb-10 border border-gray-800 shadow-2xl relative overflow-hidden">
          {/* Декоративное свечение */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-1/2 h-full bg-red-600/5 blur-[100px] pointer-events-none"></div>

          <h2 className="text-xs font-black text-red-600 uppercase tracking-[0.4em] mb-10 text-center relative z-10">
            Прогноз Нейросети
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 md:gap-4 items-center relative z-10">
            {/* Левый блок: Исход */}
            <div className="bg-black/40 p-6 rounded-3xl border border-gray-800">
              <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-4 text-center">
                Вероятность исхода
              </span>
              <div className="flex justify-between mb-3 text-[10px] font-black uppercase tracking-widest">
                <span className="text-green-500">
                  П1: {match.prediction.prob_home}%
                </span>
                <span className="text-gray-400">
                  X: {match.prediction.prob_draw}%
                </span>
                <span className="text-red-500">
                  П2: {match.prediction.prob_away}%
                </span>
              </div>
              <div className="h-3 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                <div
                  className="bg-green-500 h-full rounded-l-full"
                  style={{ width: `${match.prediction.prob_home}%` }}
                ></div>
                <div
                  className="bg-gray-500 h-full"
                  style={{ width: `${match.prediction.prob_draw}%` }}
                ></div>
                <div
                  className="bg-red-500 h-full rounded-r-full"
                  style={{ width: `${match.prediction.prob_away}%` }}
                ></div>
              </div>
            </div>

            {/* Центральный блок: Точный счет (ВЫДЕЛЕН) */}
            <div className="flex flex-col items-center justify-center p-8 bg-gray-950/50 rounded-full border-2 border-red-600/30 shadow-[0_0_40px_rgba(220,38,38,0.2)] transform hover:scale-105 transition-transform">
              <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">
                Ожидаемый счет
              </span>
              <span className="text-6xl font-black text-white italic tracking-tighter drop-shadow-[0_0_15px_rgba(255,255,255,0.5)]">
                {match.prediction.exact_score}
              </span>
            </div>

            {/* Правый блок: Тотал */}
            <div className="bg-black/40 p-6 rounded-3xl border border-gray-800">
              <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-4 text-center">
                Вероятность тотала
              </span>
              <div className="flex justify-between mb-3 text-[10px] font-black uppercase tracking-widest">
                <span className="text-purple-400">
                  ТБ 2.5: {match.prediction.total_over_2_5}%
                </span>
                <span className="text-gray-600">
                  ТМ: {100 - match.prediction.total_over_2_5}%
                </span>
              </div>
              <div className="h-3 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                <div
                  className="bg-purple-500 h-full rounded-l-full shadow-[0_0_10px_rgba(168,85,247,0.5)]"
                  style={{ width: `${match.prediction.total_over_2_5}%` }}
                ></div>
                <div
                  className="bg-gray-700 h-full rounded-r-full"
                  style={{ width: `${100 - match.prediction.total_over_2_5}%` }}
                ></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. СТАТИСТИКА (РАЗДЕЛЕНА НА АТАКУ И ОБОРОНУ) */}
      <div className="bg-gray-900 rounded-[40px] p-8 md:p-12 border border-gray-800 shadow-xl">
        <h2 className="text-xs font-black text-gray-500 uppercase tracking-[0.4em] mb-12 text-center">
          Глубокий анализ (Последние 5 матчей)
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-20">
          {/* Атакующий потенциал (Положительная статистика) */}
          <div className="space-y-8">
            <div className="text-center mb-6">
              <span className="inline-block bg-green-500/10 border border-green-500/30 text-green-500 text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full">
                Атакующий потенциал
              </span>
            </div>
            {/* Забитые голы, Созданный xG, Глубокие атаки - Чем больше, тем лучше */}
            <StatBar
              label="В среднем забито"
              h={match.homeTeam.stats_last_5.gf}
              a={match.awayTeam.stats_last_5.gf}
              color="bg-green-500"
            />
            <StatBar
              label="Созданный xG"
              h={match.homeTeam.stats_last_5.xg_for}
              a={match.awayTeam.stats_last_5.xg_for}
              color="bg-green-500"
            />
            <StatBar
              label="Глубокие проникновения"
              h={match.homeTeam.stats_last_5.deep}
              a={match.awayTeam.stats_last_5.deep}
              color="bg-green-500"
            />
          </div>

          {/* Оборонительный потенциал (Отрицательная статистика) */}
          <div className="space-y-8">
            <div className="text-center mb-6">
              <span className="inline-block bg-red-500/10 border border-red-500/30 text-red-500 text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full">
                Надежность обороны
              </span>
            </div>
            {/* Пропущенные голы, Допущенный xG, PPDA - Чем МЕНЬШЕ, тем лучше (поэтому reverse=true) */}
            <StatBar
              label="В среднем пропущено"
              h={match.homeTeam.stats_last_5.ga}
              a={match.awayTeam.stats_last_5.ga}
              reverse
              color="bg-red-500"
            />
            <StatBar
              label="Допущенный xG"
              h={match.homeTeam.stats_last_5.xg_against}
              a={match.awayTeam.stats_last_5.xg_against}
              reverse
              color="bg-red-500"
            />
            <StatBar
              label="Интенсивность прессинга"
              h={match.homeTeam.stats_last_5.ppda}
              a={match.awayTeam.stats_last_5.ppda}
              reverse
              color="bg-red-500"
            />
          </div>
        </div>
      </div>
    </div>
  );
}

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = h + a || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span
          className={`text-xl font-black ${isHomeBetter ? "text-white" : "text-gray-600"}`}
        >
          {h.toFixed(2)}
        </span>
        <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-1 text-center">
          {label}
        </span>
        <span
          className={`text-xl font-black ${!isHomeBetter ? "text-white" : "text-gray-600"}`}
        >
          {a.toFixed(2)}
        </span>
      </div>
      <div className="h-1.5 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-700"}`}
          style={{ width: `${(h / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-700"}`}
          style={{ width: `${(a / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default MatchDetailPage;
